import { DND55E_ENOA_SPELLS } from './spells-enoa.js'
// Подробные данные базовых классов D&D 5.5e (2024) для страниц /dnd55e/classes.
// DND55E_CLASS_DETAILS[название класса] → {
//   armor, weapons, tools, skills, equipment[], equipNote,
//   tableCols[], tableGrid, table[], features[]  (features: [название, источник, уровень, текст])
// }
// Тексты умений — оригинальные адаптированные формулировки механики 2024, не дословный текст книги.

