        text: 'Дороги учат обращаться с тем, что оказалось в руках. Вы можете использовать оружейные приёмы двух видов оружия, которыми вы владеете (например, скимитаров и длинных копий). После продолжительного отдыха выбор видов оружия можно сменить. На 9-м уровне число видов оружия увеличивается до трёх. Приём закреплён за конкретным оружием — ниже перечислены базовые оружейные приёмы.',
