      ['Эпическая черта', SRC, '19-й уровень', 'Вы получаете эпическую черту или другую подходящую черту, требованиям которой соответствуете. Рекомендуется [Дар пространственного путешествия](/dnd55e/feats?feat=dimensional-travel).'],
      ['Архидруид', SRC, '20-й уровень', `Жизненная сила природы постоянно расцветает внутри вас, даруя следующие эффекты:

• Неувядающая Дикая форма. Каждый раз, когда вы бросаете инициативу и у вас не осталось использований Дикой формы, вы восстанавливаете одно потраченное использование.
• Природный маг. Без действия вы можете преобразовать несколько неизрасходованных использований Дикой формы в одну ячейку заклинания; каждое использование добавляет 2 уровня ячейки. Например, два использования создают ячейку 4-го уровня. После применения этого эффекта он восстанавливается только по завершении продолжительного отдыха.
• Долголетие. Первобытная магия замедляет ваше старение: за каждые прошедшие десять лет ваше тело стареет только на 1 год.`]
