    features: [
      ['Магия договора', SRC, '1-й уровень', `Заключив договор с таинственным покровителем, вы творите заклинания колдуна на основе **Харизмы**; фокусировкой служит магическая фокусировка.

**Заговоры.** Вы знаете 2 заговора из списка колдуна — например, [Мистический заряд](/dnd55e/spells?spell=eldritch-blast) и [Фокусы](/dnd55e/spells?spell=prestidigitation); на 4-м и 10-м уровнях изучаете дополнительный.
**Ячейки заклинаний.** Все ваши ячейки — **одного (высшего доступного) круга** (столбцы «Яч.» и «Ур. яч.») и восстанавливаются уже после короткого отдыха. Например, на 5-м уровне у вас 2 ячейки 3 круга, и [Ведьмин снаряд](/dnd55e/spells?spell=witch-bolt) творится как заклинание 3 круга.
**Подготовленные заклинания.** Вы готовите список из списка колдуна (столбец «Подг. закл.»); для начала — 2 заклинания 1 круга, например [Очарование личности](/dnd55e/spells?spell=charm-person) и [Сглаз](/dnd55e/spells?spell=hex).
**Изменение.** При получении уровня одно подготовленное заклинание можно заменить другим.
**Характеристика.** Заклинательная характеристика — **Харизма**.
**Фокусировка.** Как заклинательную фокусировку используйте магическую фокусировку.`],
      {
        name: 'Таинственные воззвания', src: SRC, lvl: '1-й уровень',
        text: `Вы открываете **Таинственные воззвания** — частицы запретных знаний, дарующие постоянные магические силы (например, вечное тёмное зрение или усиление заговора) либо открывающие договоры. Начиная с одного, их число растёт по столбцу «Возз.».

**Необходимые условия.** Некоторые воззвания требуют определённого уровня колдуна — выбрать их можно, лишь достигнув его.
**Замена и получение.** При получении уровня одно воззвание можно заменить другим (если оно не требуется для другого вашего воззвания). Одно и то же воззвание нельзя выбрать дважды, если в его описании не сказано иного.`,
        itemsTitle: 'Варианты таинственных воззваний',
        itemsCollapsed: true,
        itemsExpanded: true,
        items: [
          ['Договор гримуара · Pact of the Tome', 'В конце короткого или продолжительного отдыха вы создаёте **Книгу теней**. Выберите 3 заговора и 2 заклинания 1 круга с меткой «ритуал» из списка любого класса (те, что ещё не подготовлены) — пока книга при вас, они считаются подготовленными заклинаниями колдуна. Книгу можно использовать как заклинательную фокусировку.'],
          ['Договор клинка · Pact of the Blade', 'Бонусным действием вы создаёте **оружие договора** (простое или воинское рукопашное) либо связываетесь с магическим оружием в руке; оно служит и заклинательной фокусировкой. Атакуя им, вы используете **Харизму** для бросков атаки и урона и можете менять тип урона на некротику, психику или излучение.'],
          ['Договор цепи · Pact of the Chain', 'Вы знаете «Поиск фамильяра» и творите его действием Магия без затраты ячейки. Фамильяр может принять особую форму: Бес, Псевдодракон, Квазит, Скелет, Головастик слаада, Сфинкс чудес, Спрайт или Ядовитая змея. Совершая действие Атака, вы можете вместо своей атаки позволить фамильяру атаковать за счёт его реакции.'],
          ['Доспехи теней · Armor of Shadows', 'Вы можете накладывать на себя «Доспехи мага» без затраты ячейки.'],
          ['Мистический разум · Eldritch Mind', 'Вы совершаете с преимуществом спасброски Телосложения для поддержания концентрации.'],
          ['Дьявольский взгляд · Devil’s Sight', '**Требуется:** уровень колдуна 2+. Вы нормально видите в тусклом свете и тьме (магической и немагической) в пределах 120 футов.'],
          ['Маска многих лиц · Mask of Many Faces', '**Требуется:** уровень 2+. Вы можете накладывать «Маскировка» без затраты ячейки.'],
          ['Мощь исчадия · Fiendish Vigor', '**Требуется:** уровень 2+. Вы можете накладывать на себя «Псевдожизнь» без ячейки, получая при этом **максимум** временных хитов.'],
          ['Мучительный взрыв · Agonizing Blast', '**Требуется:** уровень 2+, заговор колдуна, наносящий урон. Выберите такой заговор — вы добавляете модификатор **Харизмы** к его урону. Можно взять несколько раз (каждый раз другой заговор).'],
          ['Мистическое копьё · Eldritch Spear', '**Требуется:** уровень 2+, заговор колдуна с уроном и дистанцией 10 фт. и более. Дистанция выбранного заговора увеличивается на число футов, равное 30-кратному уровню колдуна. Можно взять несколько раз.'],
          ['Отталкивающий заряд · Repelling Blast', '**Требуется:** уровень 2+, заговор колдуна с броском атаки. Попав таким заговором по существу Большого размера или меньше, вы можете оттолкнуть его на 10 футов. Можно взять несколько раз.'],
          ['Потусторонний прыжок · Otherworldly Leap', '**Требуется:** уровень 2+. Вы можете накладывать на себя «Прыжок» без затраты ячейки.'],
          ['Туманные видения · Misty Visions', '**Требуется:** уровень 2+. Вы можете накладывать «Безмолвный образ» без затраты ячейки.'],
          ['Уроки первородных · Lessons of the First Ones', '**Требуется:** уровень 2+. Вы получаете одну **черту происхождения** на выбор. Можно взять несколько раз (каждый раз другую черту).'],
          ['Взор двух умов · Gaze of Two Minds', '**Требуется:** уровень 5+. Бонусным действием, коснувшись согласного существа, вы до конца своего следующего хода воспринимаете мир его чувствами (и можете продлевать связь бонусным действием). Пока вы оба в пределах 60 футов, вы можете творить заклинания из его пространства.'],
          ['Восходящий шаг · Ascendant Step', '**Требуется:** уровень 5+. Вы можете накладывать на себя «Левитация» без затраты ячейки.'],
          ['Дар глубин · Gift of the Depths', '**Требуется:** уровень 5+. Вы можете дышать под водой и получаете скорость плавания, равную вашей скорости; также раз на продолжительный отдых можете наложить «Подводное дыхание» без ячейки.'],
          ['Дар мастера цепи · Investment of the Chain Master', '**Требуется:** уровень 5+, Договор цепи. Ваш фамильяр из «Поиска фамильяра» получает скорость полёта или плавания 40 футов; бонусным действием вы приказываете ему атаковать; его дробящий/колющий/рубящий урон можно менять на некротику или излучение; Сл его эффектов равна Сл ваших заклинаний; реакцией вы даёте ему сопротивление получаемому урону.'],
          ['Жаждущий клинок · Thirsting Blade', '**Требуется:** уровень 5+, Договор клинка. Вы получаете **Дополнительную атаку** оружием договора — две атаки действием Атака.'],
          ['Мастер бесчисленных обликов · Master of Myriad Forms', '**Требуется:** уровень 5+. Вы можете накладывать «Смена обличья» без затраты ячейки.'],
          ['Мистическая кара · Eldritch Smite', '**Требуется:** уровень 5+, Договор клинка. Раз в ход, попав оружием договора, вы можете потратить ячейку Магии договора: цель получает 1к8 урона силовым полем плюс ещё 1к8 за каждый круг ячейки и, если её размер Огромный или меньше, получает состояние **Лежащий ничком**.'],
          ['Один среди теней · One with Shadows', '**Требуется:** уровень 5+. Находясь в тусклом свете или тьме, вы можете накладывать на себя «Невидимость» без затраты ячейки.'],
          ['Могильный шёпот · Whispers of the Grave', '**Требуется:** уровень 7+. Вы можете накладывать «Разговор с мёртвыми» без затраты ячейки.'],
          ['Видения далёких королевств · Visions of Distant Realms', '**Требуется:** уровень 9+. Вы можете накладывать «Магический глаз» без затраты ячейки.'],
          ['Дар защитников · Gift of the Protectors', '**Требуется:** уровень 9+, Договор гримуара. В Книге теней появляется страница; существа с вашего согласия могут вписать имена (до модификатора Харизмы, минимум 1). Когда хиты вписанного существа должны опуститься до 0, но оно не гибнет сразу, вместо этого они опускаются до 1. Раз на продолжительный отдых.'],
          ['Пьющий жизнь · Lifedrinker', '**Требуется:** уровень 9+, Договор клинка. Раз в ход, попав оружием, вы наносите дополнительно 1к6 урона некротикой, психикой или излучением и можете потратить Кость Хитов, восстановив хиты, равные броску + модификатор Телосложения (минимум 1).'],
          ['Пожирающий клинок · Devouring Blade', '**Требуется:** уровень 12+, воззвание Жаждущий клинок. Дополнительная атака от «Жаждущего клинка» даёт **две** дополнительные атаки вместо одной.'],
          ['Ведьмачий взор · Witch Sight', '**Требуется:** уровень 15+. Вы получаете **истинное зрение** в пределах 30 футов и видите в магической и немагической тьме.']
        ]
      },
      ['Магическая хитрость', SRC, '2-й уровень', 'Проведя эзотерический ритуал длительностью 1 минуту, вы восстанавливаете потраченные ячейки Магии договора — **но не более половины** их максимума (округляя вверх). Повторно — только после продолжительного отдыха.'],
      ['Подкласс колдуна', SRC, '3-й уровень', `Вы выбираете подкласс — покровителя; он даёт заклинания и умения на **3, 6, 10 и 14** уровнях. Доступные покровители:

• **Архифея**;
• **Небожитель**;
• **Исчадие**;
• **Великий Древний**.`],
      ['Улучшение характеристик', SRC, '4-й уровень', 'Вы получаете черту **Улучшение характеристик** или другую подходящую черту. Повторяется на **8, 12 и 16** уровнях.'],
      ['Связь с покровителем', SRC, '9-й уровень', `Вы можете связываться с покровителем напрямую: у вас всегда подготовлено заклинание [Связь с иным планом](/dnd55e/spells?spell=contact-other-plane).

Вы можете сотворить его **без затраты ячейки**, чтобы обратиться к покровителю, и **автоматически преуспеваете** в спасброске от него. Повторно — только после продолжительного отдыха.`],
      ['Таинственный арканум', SRC, '11-й уровень', `Покровитель дарует вам **арканум** — заклинание 6 круга из списка колдуна, которое вы творите **один раз без ячейки**, восстанавливая его на продолжительном отдыхе.

Вы получаете ещё по аркануму на **13** (7 круг), **15** (8 круг) и **17** (9 круг) уровнях. При повышении уровня один арканум можно заменить другим заклинанием того же круга.`],
      ['Эпическая черта', SRC, '19-й уровень', 'Вы получаете **эпическую черту** или другую подходящую черту (рекомендуется [Дар судьбы](/dnd55e/feats?feat=fate)).'],
      ['Таинственный мастер', SRC, '20-й уровень', 'Когда вы используете **Магическую хитрость**, вы восстанавливаете **все** потраченные ячейки Магии договора.']
    ]
